import {
  Mjml,
  MjmlBody,
  MjmlButton,
  MjmlFont,
  MjmlHead,
  MjmlImage,
  MjmlNavbar,
  MjmlNavbarLink,
  MjmlPreview,
  MjmlSocial,
  MjmlSocialElement,
  MjmlText,
  MjmlWrapper,
  MjmlColumn,
  MjmlSection,
  MjmlDivider,
} from "@faire/mjml-react";
import type { ReactNode } from "react";

import type { EmailTheme } from "@/components/email/email-theme";
import { emailAsset } from "@/components/email/email-assets";
import { defaultTheme } from "@/components/email/theme-default";

const resolveDefaultProps = <Defaults extends object, Props extends object>(
  defaults: Defaults,
  props: Props
) => {
  const supplied = props as Record<string, unknown>;
  const fallbackEntries = Object.entries(defaults).map(([key, value]) => [
    key,
    supplied[key] === undefined ? value : supplied[key],
  ]);

  return {
    ...defaults,
    ...props,
    ...Object.fromEntries(fallbackEntries),
  } as Defaults & Props;
};

const fontFamily =
  'Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif';

interface NativeFooterLink {
  href: string;
  label: string;
}

interface NativeFooterSocial extends NativeFooterLink {
  iconSrc: string;
}

const FooterEmailShell = ({
  children,
  pageBackgroundColor,
  preview = "Footer",
  theme,
}: {
  children: ReactNode;
  pageBackgroundColor: string;
  preview?: string;
  theme: EmailTheme;
}) => (
  <Mjml>
    <MjmlHead>
      <MjmlPreview>{preview}</MjmlPreview>
      <MjmlFont href="https://rsms.me/inter/inter.css" name="Inter" />
    </MjmlHead>
    <MjmlBody
      backgroundColor={pageBackgroundColor}
      width={theme.containerWidth}
    >
      <MjmlWrapper padding="0">{children}</MjmlWrapper>
    </MjmlBody>
  </Mjml>
);

const FooterLogo = ({
  align = "left",
  alt,
  href,
  padding = "0",
  src,
  width = "48px",
}: {
  align?: "center" | "left" | "right";
  alt: string;
  href: string;
  padding?: string;
  src: string;
  width?: string;
}) => (
  <MjmlImage
    align={align}
    alt={alt}
    href={href}
    padding={padding}
    src={src}
    width={width}
  />
);

const FooterCopy = ({
  align = "left",
  children,
  color,
  fontSize = "14px",
  fontWeight = "400",
  lineHeight = "22px",
  padding = "0",
}: {
  align?: "center" | "left" | "right";
  children: ReactNode;
  color: string;
  fontSize?: string;
  fontWeight?: string;
  lineHeight?: string;
  padding?: string;
}) => (
  <MjmlText
    align={align}
    color={color}
    fontFamily={fontFamily}
    fontSize={fontSize}
    fontWeight={fontWeight}
    lineHeight={lineHeight}
    padding={padding}
  >
    {children}
  </MjmlText>
);

const FooterMenu = ({
  align = "left",
  links,
  textColor,
}: {
  align?: "center" | "left" | "right";
  links: NativeFooterLink[];
  textColor: string;
}) => (
  <MjmlNavbar align={align} padding="0">
    {links.map((link) => (
      <MjmlNavbarLink
        color={textColor}
        fontFamily={fontFamily}
        fontSize="14px"
        href={link.href}
        key={`${link.label}-${link.href}`}
        padding="4px 10px"
      >
        {link.label}
      </MjmlNavbarLink>
    ))}
  </MjmlNavbar>
);

const FooterVerticalMenu = ({
  align = "left",
  heading,
  headingColor,
  links,
  textColor,
}: {
  align?: "center" | "left" | "right";
  heading: string;
  headingColor: string;
  links: NativeFooterLink[];
  textColor: string;
}) => (
  <>
    <FooterCopy
      align={align}
      color={headingColor}
      fontWeight="600"
      padding="0 0 8px"
    >
      {heading}
    </FooterCopy>
    {links.map((link) => (
      <MjmlButton
        align={align}
        backgroundColor="transparent"
        color={textColor}
        fontFamily={fontFamily}
        fontSize="14px"
        href={link.href}
        innerPadding="0"
        key={`${link.label}-${link.href}`}
        lineHeight="24px"
        padding="2px 0"
      >
        {link.label}
      </MjmlButton>
    ))}
  </>
);

const FooterSocials = ({
  align = "left",
  socials,
}: {
  align?: "center" | "left" | "right";
  socials: NativeFooterSocial[];
}) => (
  <MjmlSocial align={align} iconSize="24px" mode="horizontal" padding="0">
    {socials.map((social) => (
      <MjmlSocialElement
        alt={social.label}
        href={social.href}
        key={`${social.label}-${social.href}`}
        name={social.label.toLowerCase()}
        padding="4px"
        src={social.iconSrc}
      />
    ))}
  </MjmlSocial>
);

const FooterLegal = ({
  align = "left",
  copyright,
  mutedTextColor,
  unsubscribeHref,
}: {
  align?: "center" | "left" | "right";
  copyright: string;
  mutedTextColor: string;
  unsubscribeHref: string;
}) => (
  <>
    <FooterCopy align={align} color={mutedTextColor}>
      {copyright}
    </FooterCopy>
    <MjmlButton
      align={align}
      backgroundColor="transparent"
      color={mutedTextColor}
      fontFamily={fontFamily}
      fontSize="12px"
      href={unsubscribeHref}
      innerPadding="0"
      lineHeight="20px"
      padding="4px 0 0"
      textDecoration="underline"
    >
      Unsubscribe
    </MjmlButton>
  </>
);

const FooterCta = ({
  align = "left",
  backgroundColor,
  color,
  href,
  label,
  padding = "20px 0 0",
}: {
  align?: "center" | "left" | "right";
  backgroundColor: string;
  color: string;
  href: string;
  label: string;
  padding?: string;
}) => (
  <MjmlButton
    align={align}
    backgroundColor={backgroundColor}
    borderRadius="8px"
    color={color}
    fontFamily={fontFamily}
    fontSize="15px"
    fontWeight="600"
    href={href}
    innerPadding="12px 22px"
    padding={padding}
  >
    {label}
  </MjmlButton>
);

type ContentCtaFooter_FooterWithContentAndCtaVariant =
  | "centered"
  | "left-aligned"
  | "right-aligned";

interface ContentCtaFooter_FooterWithContentAndCtaProps {
  theme?: EmailTheme;
  heading?: string;
  subtext?: string;
  ctaLabel?: string;
  ctaHref?: string;
  logoSrc?: string;
  logoAlt?: string;
  updatePreferencesHref?: string;
  unsubscribeHref?: string;
  pageBackgroundColor?: string;
  backgroundColor?: string;
  headingColor?: string;
  textColor?: string;
  mutedTextColor?: string;
  buttonColor?: string;
  buttonTextColor?: string;
  variant?: ContentCtaFooter_FooterWithContentAndCtaVariant;
}

const ContentCtaFooter_defaults = {
  backgroundColor: "#fffffe",
  buttonColor: "#4f46e5",
  buttonTextColor: "#fffffe",
  ctaHref: "https://example.com",
  ctaLabel: "Visit website",
  heading: "Start sending professionally\ndesigned emails today",
  headingColor: "#030712",
  logoAlt: "Maizzle",
  logoSrc: emailAsset("maizzle-insignia.png"),
  mutedTextColor: "#d1d5db",
  pageBackgroundColor: "#f1f5f9",
  subtext:
    "Lorem ipsum dolor sit amet consectetur. Eget aenean sed sit sed in sapien. Vel auctor arcu nulla consectetur sed.",
  textColor: "#6b7280",
  unsubscribeHref: "https://example.com/unsub",
  updatePreferencesHref: "https://example.com/update",
};

type ContentCtaFooter_SectionProps = Omit<
  ContentCtaFooter_FooterWithContentAndCtaProps,
  "theme"
>;

const ContentCtaFooter_FooterWithContentAndCtaSection = (
  props: ContentCtaFooter_SectionProps
) => {
  const resolved = resolveDefaultProps(ContentCtaFooter_defaults, props);
  let align: "center" | "left" | "right" = "center";
  if (resolved.variant === "left-aligned") {
    align = "left";
  } else if (resolved.variant === "right-aligned") {
    align = "right";
  }
  return (
    <MjmlSection
      backgroundColor={resolved.backgroundColor}
      padding="44px 24px 24px"
    >
      <MjmlColumn>
        <FooterCopy
          align={align}
          color={resolved.headingColor}
          fontSize="20px"
          fontWeight="600"
          lineHeight="28px"
        >
          {resolved.heading}
        </FooterCopy>
        <FooterCopy
          align={align}
          color={resolved.textColor}
          fontSize="16px"
          lineHeight="24px"
          padding="24px 0 0"
        >
          {resolved.subtext}
        </FooterCopy>
        <FooterCta
          align={align}
          backgroundColor={resolved.buttonColor}
          color={resolved.buttonTextColor}
          href={resolved.ctaHref}
          label={resolved.ctaLabel}
          padding="28px 0"
        />
        <FooterLogo
          align={align}
          alt={resolved.logoAlt}
          href="https://example.com"
          src={resolved.logoSrc}
          width="48px"
        />
        <FooterLegal
          align={align}
          copyright="© 2026 emailcn. Update preferences at any time."
          mutedTextColor={resolved.mutedTextColor}
          unsubscribeHref={resolved.unsubscribeHref}
        />
      </MjmlColumn>
    </MjmlSection>
  );
};

const ContentCtaFooter_FooterWithContentAndCta = ({
  pageBackgroundColor = ContentCtaFooter_defaults.pageBackgroundColor,
  theme = defaultTheme,
  ...props
}: ContentCtaFooter_FooterWithContentAndCtaProps) => (
  <FooterEmailShell pageBackgroundColor={pageBackgroundColor} theme={theme}>
    <ContentCtaFooter_FooterWithContentAndCtaSection {...props} />
  </FooterEmailShell>
);

ContentCtaFooter_FooterWithContentAndCta.PreviewProps = {
  theme: defaultTheme,
  variant: "centered",
} satisfies ContentCtaFooter_FooterWithContentAndCtaProps;

const __ContentCtaFooter = ContentCtaFooter_FooterWithContentAndCta;

